import{filterDeals,activeDeals,easternDate,googleMapsUrl}from'./model.mjs?v=bdb91c4e333f';
const data=JSON.parse(document.getElementById('deal-data').textContent),form=document.getElementById('filters'),results=document.getElementById('results');const names=['day','town','kind','query'];const params=new URLSearchParams(location.search);for(const key of names){const el=form.elements[key];if(params.has(key))el.value=params.get(key);if(el.tagName==='SELECT'&&el.selectedIndex<0)el.selectedIndex=0;}
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
let lastRenderedDate;
function render(){const now=new Date(),date=easternDate(now),weekday=new Intl.DateTimeFormat('en-US',{weekday:'long',timeZone:'America/New_York'}).format(now),dayNumber=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].indexOf(weekday);form.elements.day.options[0].textContent=`Today · ${weekday}`;lastRenderedDate=date;const state=Object.fromEntries(names.map(n=>[n,form.elements[n].value]));const filtered=filterDeals(activeDeals(data,now),{...state,day:state.day==='today'?dayNumber:state.day});document.getElementById('results-title').textContent=state.day==='today'?'On the menu today':state.day==='all'?'Your next good meal':`${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][state.day]} finds`;document.getElementById('count').textContent=`${filtered.length} ${filtered.length===1?'deal':'deals'}`;document.getElementById('schedule-note').textContent=state.day==='today'?'Scheduled for today. Check each offer’s serving hours.':'Offers listed by restaurants. Confirm before ordering.';const focused=document.activeElement;const focusedDeal=focused?.closest?.('.deal')?.dataset.dealId;const focusedHref=focused?.getAttribute?.('href');results.innerHTML=filtered.map(d=>{const age=(Date.parse(date)-Date.parse(d.lastChecked))/86400000;return `<article class="deal" data-deal-id="${esc(d.id)}"><div class="deal-top"><span class="badge">${esc(d.timeLabel)}</span><span>${esc(d.town)}</span></div><div class="price">${esc(d.priceLabel)}</div><h3>${esc(d.title)}</h3><p class="restaurant">${esc(d.restaurant)}</p><div class="deal-location"><p class="address">${esc(d.address)}</p><a href="${esc(googleMapsUrl(d))}" target="_blank" rel="noopener noreferrer" aria-label="${esc(d.restaurant)} on Google Maps (opens in a new tab)">Google Maps ↗</a></div><p class="terms">${esc(d.terms)}</p><div class="deal-foot"><span>${age>14?'Recheck recommended · ':''}Website checked ${esc(d.lastChecked)}</span><a href="${esc(d.sourceUrl)}" target="_blank" rel="noopener noreferrer">View offer ↗</a></div></article>`;}).join('')||'<div class="empty"><h3>No deals match just yet.</h3><p>Try another day, town, or type of meal.</p><button type="button" id="empty-reset">Show all deals</button></div>';if(focusedDeal){const card=Array.from(results.querySelectorAll('.deal')).find(node=>node.dataset.dealId===focusedDeal);const link=card&&Array.from(card.querySelectorAll('a')).find(node=>node.getAttribute('href')===focusedHref);(link||document.getElementById('reset')).focus();}document.getElementById('empty-reset')?.addEventListener('click',()=>reset('all'));const p=new URLSearchParams(location.search);names.forEach(k=>p.delete(k));const ui=p.getAll('ui');p.delete('ui');if(ui.length===1&&['default','modern','modern-list','ocean','ocean-list','local','ticket','table','local-ocean','ticket-ocean','table-ocean'].includes(ui[0]))p.set('ui',ui[0]);names.forEach(k=>{if(state[k]&&state[k]!==({day:'today',town:'all',kind:'all',query:''}[k]))p.set(k,state[k]);});history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash);document.getElementById('updated').textContent='Listings updated '+new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/New_York'}).format(new Date(data.updatedAt));}
function reset(day='today'){form.reset();form.elements.day.value=day;render();}form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',render);document.getElementById('reset').addEventListener('click',()=>reset());render();function refreshDate(){if(easternDate(new Date())!==lastRenderedDate)render();}setInterval(refreshDate,60000);document.addEventListener?.('visibilitychange',()=>{if(!document.hidden)refreshDate();});
